import java.util.*;
class Shop {
    private String name; private int nsold;
    public Shop(String s, int n) { name=s; nsold=n; }
    public String getName() { return name; }
    public int getItemSold() { return nsold; }
}
public class MapTest {
    // █ FILLED BY STUDENT: Define printShopName(ArrayList<Shop> sList); LinkedHashMap + getOrDefault, then find max entry and print
    public static void printShopName(ArrayList<Shop> sList) {
        Map<String,Integer> m = new LinkedHashMap<>();
        String shop = ""; int sold = 0;
        for (Shop s : sList)
            m.put(s.getName(), m.getOrDefault(s.getName(), 0) + s.getItemSold());
        for (Map.Entry<String,Integer> e : m.entrySet())
            if (e.getValue() > sold) { sold = e.getValue(); shop = e.getKey(); }
        System.out.println(shop + " : " + sold);
    }


    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        ArrayList<Shop> list = new ArrayList<>();
        for(int i=0;i<4;i++) list.add(new Shop(sc.next(), sc.nextInt()));
        printShopName(list);
    }
}

