// █ FILLED BY STUDENT: Define class ArrayExample<T>; T[] a; constructor; display(); elementCount(T x)
class ArrayExample<T> {
    T[] a;
    public ArrayExample(T[] ob) { a = ob; }
    public void display() {
        for (int i=0; i<a.length; i++) System.out.print(a[i]+" ");
        System.out.println();
    }
    public int elementCount(T x) {
        int count = 0;
        for (int i=0; i<a.length; i++) if (a[i].equals(x)) count++;
        return count;
    }
}


