import java.util.*;
class Bills {
    static double discount = 0.1;
    private String name;
    private String[] items;
    private int billAmt;
    private double discountedAmt;

    // █ FILLED BY STUDENT: discountedAmt = billAmt - (billAmt * discount)
    public Bills(String n, int amt, String[] it) {
        this.name = n; this.billAmt = amt; this.items = it;
        this.discountedAmt = this.billAmt - (this.billAmt * discount);
    }

    // █ FILLED BY STUDENT: Define constructor Bills()
    public Bills(Bills b) {
        this.name = b.name; this.billAmt = b.billAmt; this.discountedAmt = b.discountedAmt;
        this.items = new String[b.items.length];
        for (int i = 0; i < b.items.length; i++) this.items[i] = b.items[i];
    }

    // █ FILLED BY STUDENT: Implement getName()
    public String getName() { return this.name; }

    // █ FILLED BY STUDENT: Implement getDiscountAmt()
    public double getDiscountAmt() { return this.discountedAmt; }

    // █ FILLED BY STUDENT: Implement changeItem()
    public void changeItem(String itemName) { this.items[0] = itemName; }

    // █ FILLED BY STUDENT: Implement printBill()
    public void printBill() {
        System.out.println("Name : "+name);
        System.out.println("Bill Amount : "+billAmt);
        System.out.println("Discounted Amount : "+discountedAmt);
        System.out.print("Items : ");
        for (String s : items) System.out.print(s+" : ");
    }
}

public class Main {
    public static void main(String args[]) {
